<?php require_once __DIR__.'/auth.php'; require_admin(); $pdo=db(); $keys=['name','shortName','phone','email','address','founded']; $error=''; $message=''; if($_SERVER['REQUEST_METHOD']==='POST'){ if (!csrf_check()) { $error='Your session expired — please try saving again.'; } else { foreach($keys as $k){$st=$pdo->prepare('INSERT INTO site_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');$st->execute([$k,trim($_POST[$k]??'')]);}$message='Settings saved.'; } } $settings=[];foreach($pdo->query('SELECT setting_key,setting_value FROM site_settings') as $r)$settings[$r['setting_key']]=$r['setting_value'];?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Website Settings — Admin</title><meta name="robots" content="noindex, nofollow"><link href="https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Karla:wght@400;500;700&family=IBM+Plex+Mono:wght@400;500&display=swap" rel="stylesheet"><link rel="stylesheet" href="../assets/css/admin.css"></head><body><div class="top"><b>Strata &amp; Beam Admin — Settings</b><a href="index.php">Dashboard</a></div><div class="wrap"><div class="box"><a href="index.php" class="muted">&larr; Dashboard</a><h1>Website Settings</h1><?php if($error):?><p class="err"><?php echo htmlspecialchars($error);?></p><?php endif;?><?php if(!empty($message))echo '<p class="ok">'.htmlspecialchars($message).'</p>';?><form method="post"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars(csrf_token());?>"><?php foreach($keys as $k):?><label><?php echo htmlspecialchars($k);?><input name="<?php echo $k;?>" value="<?php echo htmlspecialchars($settings[$k]??'');?>"></label><?php endforeach;?><button>Save Settings</button></form></div></div></body></html>
